const QDRANT_URL = 'http://qdrant:6333';
const QDRANT_API_KEY = process.env.QDRANT_API_KEY || '';
const OLLAMA_URL = 'http://host.docker.internal:11434';

async function qdrantScroll(collection, filter, limit=100) {
  const body = {limit, with_payload: true, with_vector: false};
  if (filter) body.filter = filter;
  const r = await fetch(`${QDRANT_URL}/collections/${collection}/points/scroll`, {
    method: 'POST', headers: {'api-key': QDRANT_API_KEY, 'Content-Type': 'application/json'},
    body: JSON.stringify(body)
  });
  const d = await r.json();
  return d.result?.points || [];
}

async function qdrantStore(collection, id, vector, payload) {
  await fetch(`${QDRANT_URL}/collections/${collection}/points`, {
    method: 'PUT', headers: {'api-key': QDRANT_API_KEY, 'Content-Type': 'application/json'},
    body: JSON.stringify({points: [{id, vector, payload}]})
  });
}

async function qdrantUpdate(collection, ids, payload) {
  await fetch(`${QDRANT_URL}/collections/${collection}/points/payload`, {
    method: 'POST', headers: {'api-key': QDRANT_API_KEY, 'Content-Type': 'application/json'},
    body: JSON.stringify({payload, points: ids})
  });
}

async function embed(text) {
  const r = await fetch(`${OLLAMA_URL}/api/embed`, {
    method: 'POST', headers: {'Content-Type': 'application/json'},
    body: JSON.stringify({model: 'nomic-embed-text', input: text})
  });
  const d = await r.json();
  return d.embeddings?.[0] || null;
}

function uuid() { return crypto.randomUUID(); }

const memories = await qdrantScroll('claude_memories', null, 500);
const now = Date.now();
const candidates = [];

for (const m of memories) {
  const payload = m.payload || {};
  const created = new Date(payload.created_at || 0).getTime();
  const ageDays = (now - created) / (24 * 60 * 60 * 1000);
  const recallCount = payload.recall_count || 0;
  const status = payload.status || 'active';
  const confidence = payload.confidence || 1.0;

  let reason = null;
  if (status === 'superseded') reason = 'superseded by newer memory';
  else if (confidence < 0.2) reason = 'low confidence (' + confidence + ')';
  else if (ageDays > 180 && recallCount === 0) reason = 'unused for ' + Math.floor(ageDays) + ' days';

  if (reason) {
    candidates.push({id: m.id, content: (payload.content || '').slice(0, 100), reason, ageDays: Math.floor(ageDays), recallCount});
  }
}

// Soft delete: move to memories_cold
let pruned = 0;
for (const c of candidates.slice(0, 50)) { // max 50 per run
  const m = memories.find(m => m.id === c.id);
  if (!m) continue;
  const vec = await embed(m.payload?.content || '');
  if (vec) {
    await qdrantStore('memories_cold', m.id, vec, {
      ...m.payload, pruned_at: new Date().toISOString(),
      prune_reason: c.reason, original_collection: 'claude_memories',
      retention_expires: new Date(now + 90 * 24 * 60 * 60 * 1000).toISOString()
    });
    pruned++;
  }
}

// Log to audit
const auditVec = await embed('pruning cycle ' + pruned + ' memories pruned');
if (auditVec) {
  await qdrantStore('audit_log', uuid(), auditVec, {
    action: 'MEMORY_PRUNED_BATCH', timestamp: new Date().toISOString(),
    details: {candidates: candidates.length, pruned, reasons: candidates.slice(0,10).map(c=>c.reason)},
    sensitivity: 'internal', project: 'global'
  });
}

return [{json: {candidates: candidates.length, pruned}}];
